/* Measurement scaling and plausibility for the controller board's analog and digital inputs.
 *
 * Portable (no registers): the STM32G4 platform layer calls these with raw ADC counts and pin
 * levels, and the host tests check them. Each converter is built from calibration values; a
 * converter whose values are missing is "not configured" and reports its signal as missing, so a
 * hardware build without bench calibration never produces a usable measurement from it.
 *
 * Circuits assumed here are the ones drawn in hardware/kicad (generated by tools/gen_kicad_schematic.py):
 *   temperature (sheet 07): bias resistor from +3V3A to the sense node, NTC from the node to ground;
 *                           the ADC reference is +3V3A, so the reading is ratiometric.
 *   pedal (sheet 10):       connector -> 10k -> ADC pin -> 18k -> ground (ratio in the calibration).
 *   phase current:          low-side shunt -> amplifier -> ADC; offset and gain in the calibration.
 */
#ifndef SEMMC_MC_IO_H
#define SEMMC_MC_IO_H

#include <stdbool.h>
#include <stdint.h>

#include "semmc/mc_control.h"
#include "semmc/mc_types.h"

/* A ratiometric reading at or beyond these fractions of full scale is an open or shorted sensor
 * (design values: they depend only on the divider topology, not on the sensor). */
#define MC_NTC_RATIO_MIN 0.01f
#define MC_NTC_RATIO_MAX 0.99f

/* ---- NTC thermistor ----------------------------------------------------------------- */
typedef struct {
    float r25_ohm, beta_K, bias_ohm;
    bool configured;
} mc_ntc_t;

void mc_ntc_init(mc_ntc_t *n, float r25_ohm, float beta_K, float bias_ohm);
/* ratio = node voltage / analog supply, 0..1. */
float mc_ntc_temp_degC(const mc_ntc_t *n, float ratio, mc_validity_t *val);

/* ---- redundant two-track pedal ---------------------------------------------------- */
typedef struct {
    float a_rel_V, a_full_V, b_rel_V, b_full_V;  /* at the connector */
    float tol;                                   /* fraction of travel */
    float divider;                               /* connector voltage / ADC pin voltage */
    bool configured;
} mc_pedal_t;

typedef struct {
    float throttle;      /* 0..1; 0 when invalid */
    bool valid;
    float frac_a, frac_b; /* each track's travel fraction, for diagnostics */
} mc_pedal_out_t;

void mc_pedal_init(mc_pedal_t *p, float a_rel_V, float a_full_V, float b_rel_V, float b_full_V, float tol,
                   float divider);
/* va, vb: voltages at the ADC pins. */
void mc_pedal_eval(const mc_pedal_t *p, float va_pin_V, float vb_pin_V, mc_pedal_out_t *out);

/* ---- ADC scaling ---------------------------------------------------------------------- */
typedef struct {
    float vref_V;
    float full_scale;        /* 2^bits */
    float amps_per_count;    /* signed: includes the amplifier polarity */
    float offset[3];         /* zero-current counts in use (bench value, or the boot measurement) */
    float offset_cal[3];     /* bench value from the calibration */
    float offset_tol;        /* counts */
    float vbus_ratio;
    bool current_configured;
    bool vbus_configured;
} mc_adc_scale_t;

/* polarity: 0 = reading rises with current into the terminal, 1 = falls (config current_polarity). */
void mc_adc_scale_init(mc_adc_scale_t *s, float vref_V, float bits, float shunt_ohm, float gain, float polarity,
                       const float offset_counts[3], float offset_tol_counts, float vbus_ratio);
static inline float mc_adc_volts(const mc_adc_scale_t *s, uint32_t counts)
{
    return (float)counts * s->vref_V / s->full_scale;
}
static inline float mc_adc_phase_A(const mc_adc_scale_t *s, int k, uint32_t counts)
{
    return ((float)counts - s->offset[k]) * s->amps_per_count;
}
float mc_adc_vbus_V(const mc_adc_scale_t *s, uint32_t counts, mc_validity_t *val);
/* Boot self-test: zero-current readings measured with the gate driver disabled. Uses the measured
 * offsets when every phase is within tolerance of the bench value and returns true; otherwise keeps
 * the bench values and returns false (the core then refuses to arm). */
bool mc_adc_accept_offsets(mc_adc_scale_t *s, const float measured[3]);

/* ---- low-side sampling window ----------------------------------------------------------- */
/* Phases whose low-side switch was on long enough around the PWM valley for a valid sample:
 * duty <= 1 - 2 (deadtime + settle) f_pwm (validator rule R15b). With the outputs off every
 * phase is reported measured: the core needs a sample to start, and at standstill it is zero. */
uint8_t mc_lowside_sample_mask(const mc_duty_t *applied, bool outputs_on, float deadtime_s, float settle_s,
                               float f_pwm_Hz);

/* ---- driver-enable path check ----------------------------------------------------------- */
/* The board gates the driver's ENABLE as MCU_DRV_EN AND HW_PERMIT (74LVC1G08) and feeds the result
 * back to the MCU. A disagreement on two consecutive checks is a latched fault: the gate, its supply
 * or the feedback is broken, and the hardware interlock can no longer be trusted. */
typedef struct {
    uint8_t mismatch_run;
    bool fault;
} mc_enable_check_t;

bool mc_enable_path_check(mc_enable_check_t *e, bool mcu_en, bool hw_permit, bool gated);

#endif /* SEMMC_MC_IO_H */
